def solve(inputs: dict) -> float:
    mods = None
    rems = None
    for k, v in inputs.items():
        if isinstance(v, (list, tuple)):
            lk = str(k).lower()
            if 'mod' in lk:
                mods = list(v)
            elif 'rem' in lk:
                rems = list(v)
    # fallback if keys unknown: assume two lists present
    if mods is None or rems is None:
        lists = [list(v) for v in inputs.values() if isinstance(v, (list, tuple))]
        if len(lists) >= 2:
            # rems typically smaller than mods elementwise
            a, b = lists[0], lists[1]
            if all(x < y for x, y in zip(a, b)):
                rems, mods = a, b
            else:
                rems, mods = b, a
    # CRT
    x = 0
    M = 1
    for m in mods:
        M *= m
    result = 0
    for r, m in zip(rems, mods):
        Mi = M // m
        # inverse of Mi mod m
        inv = pow(Mi, -1, m)
        result += r * Mi * inv
    result %= M
    return float(result)

