def solve(inputs: dict) -> float:
    g = x = p = None
    for k, v in inputs.items():
        if isinstance(v, (int, float)):
            lk = str(k).lower()
            if lk == 'g' or 'base' in lk:
                g = int(v)
            elif lk == 'x' or 'exp' in lk:
                x = int(v)
            elif lk == 'p' or 'mod' in lk:
                p = int(v)
    if g is None or x is None or p is None:
        vals = [int(v) for v in inputs.values() if isinstance(v, (int, float))]
        # heuristic: exponent is the smallest
        if len(vals) == 3:
            vals_sorted = sorted(vals)
            x = vals_sorted[0]
            rem = [v for v in vals if v != x]
            g, p = rem[0], rem[1]
    return float(pow(g, x, p))

